"""Read side: a projector turns events into a query-shaped read model. Run the demo: python app.py

Works on the happy path. Hidden weakness (the failureLab): the checkpoint moves BEFORE the read model changes,
in a separate transaction, and the counters are not idempotent. A crash in between skips an event for good.
"""
import json
import sqlite3
import sys
import time

READ_SCHEMA = """
CREATE TABLE IF NOT EXISTS member_loans (member_id TEXT PRIMARY KEY, active INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS book_status (book_id TEXT PRIMARY KEY, member_id TEXT);
CREATE TABLE IF NOT EXISTS checkpoint (projector TEXT PRIMARY KEY, seq INTEGER NOT NULL);
"""


class SimulatedCrash(Exception):
    """Seeded fault: the projector process dies at a chosen event."""


def json_log(record, stream=sys.stdout):
    print(json.dumps(record, sort_keys=True), file=stream)  # structured log: one JSON object per line


class Projector:
    name = "loans_view"

    def __init__(self, store, read_db=None, log=json_log, crash_at_seq=None):
        self.store, self.log, self.crash_at_seq = store, log, crash_at_seq
        self.db = read_db or sqlite3.connect(":memory:", check_same_thread=False)  # read model: its own database
        self.db.executescript(READ_SCHEMA)

    def position(self):  # checkpoint: the last event seq this projector has handled
        row = self.db.execute("SELECT seq FROM checkpoint WHERE projector = ?", (self.name,)).fetchone()
        return row[0] if row else 0

    def _save_checkpoint(self, seq):
        with self.db:
            self.db.execute("INSERT OR REPLACE INTO checkpoint VALUES (?, ?)", (self.name, seq))

    def apply(self, event_type, data):
        member, book = data["memberId"], data["bookId"]
        delta = 1 if event_type == "LoanCreated" else -1  # NOT idempotent: applying twice counts twice
        self.db.execute("INSERT INTO member_loans VALUES (?, 0) ON CONFLICT(member_id) DO NOTHING", (member,))
        self.db.execute("UPDATE member_loans SET active = active + ? WHERE member_id = ?", (delta, member))
        self.db.execute("INSERT OR REPLACE INTO book_status VALUES (?, ?)",
                        (book, member if event_type == "LoanCreated" else None))

    def run_once(self):
        events = self.store.read_after(self.position())
        for seq, event_type, data, recorded_at in events:
            self._save_checkpoint(seq)  # weakness: position moves first, in its own transaction ...
            if seq == self.crash_at_seq:
                raise SimulatedCrash(f"projector died at seq {seq}")
            with self.db:  # ... the read model changes in a second transaction
                self.apply(event_type, data)
            # consistency window: time from the write-side commit to this event being visible in the view
            self.log({"evt": "projected", "projector": self.name, "seq": seq, "type": event_type,
                      "lag_ms": round((time.time() - recorded_at) * 1000, 1)})
        return len(events)

    def rebuild(self):
        """Drop the view and replay every event from seq 0: the read model is disposable, the log is not."""
        with self.db:
            self.db.execute("DELETE FROM member_loans")
            self.db.execute("DELETE FROM book_status")
            self.db.execute("DELETE FROM checkpoint WHERE projector = ?", (self.name,))
        replayed = 0
        while (count := self.run_once()):
            replayed += count
        self.log({"evt": "rebuilt", "projector": self.name, "replayed": replayed, "position": self.position()})
        return replayed


class LoansView:
    """Queries: cheap, shaped for the screen, and possibly a few milliseconds behind the write side."""

    def __init__(self, db):
        self.db = db

    def active_loans(self, member_id):
        row = self.db.execute("SELECT active FROM member_loans WHERE member_id = ?", (member_id,)).fetchone()
        return row[0] if row else 0

    def holder(self, book_id):
        row = self.db.execute("SELECT member_id FROM book_status WHERE book_id = ?", (book_id,)).fetchone()
        return row[0] if row else None

    def snapshot(self):
        return {"member_loans": dict(self.db.execute("SELECT * FROM member_loans ORDER BY member_id").fetchall()),
                "book_status": dict(self.db.execute("SELECT * FROM book_status ORDER BY book_id").fetchall())}


def drift(store, view_db, projector_cls=None):
    """Projection check: rebuild into a scratch database and list every row where the live view differs."""
    fresh = (projector_cls or Projector)(store, log=lambda record: None)
    fresh.rebuild()
    live, truth = LoansView(view_db).snapshot(), LoansView(fresh.db).snapshot()
    return [f"{table}[{key}]: view {live[table].get(key)!r}, events say {truth[table].get(key)!r}"
            for table in truth for key in sorted(set(truth[table]) | set(live[table]))
            if live[table].get(key) != truth[table].get(key)]

"""Resilience patterns around a flaky dependency: timeout, circuit breaker, bulkhead, fallback (lesson 13 lab code).

Stdlib only. Same ideas as resilience4j (Java) and Polly (.NET). Run the demo: python app.py
"""
import json
import sys
import threading
import time
from collections import deque
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout


def json_log(record, stream=sys.stdout):
    print(json.dumps(record, sort_keys=True), file=stream)  # structured log: one JSON object per line


class CircuitOpen(Exception):
    pass


class BulkheadFull(Exception):
    pass


class Pool:
    """Worker threads with a busy gauge. A timeout frees the CALLER, not the worker thread."""

    def __init__(self, name, workers):
        self.name, self.workers, self.busy, self._lock = name, workers, 0, threading.Lock()
        self.executor = ThreadPoolExecutor(max_workers=workers, thread_name_prefix=name)

    def _run(self, fn, args):
        with self._lock:
            self.busy += 1
        try:
            return fn(*args)
        finally:
            with self._lock:
                self.busy -= 1

    def call(self, fn, *args, timeout):
        future = self.executor.submit(self._run, fn, args)
        try:
            return future.result(timeout=timeout)  # timeout: stop WAITING after `timeout` s ...
        except FutureTimeout:
            future.cancel()  # ... but a call that already started keeps its thread until it returns
            raise TimeoutError(f"{self.name}: no answer within {timeout} s") from None

    def shutdown(self):
        self.executor.shutdown(wait=False, cancel_futures=True)


class Bulkhead(Pool):
    """Pool + semaphore for ONE dependency: at most `workers` calls in flight, the next is rejected at once."""

    def __init__(self, name, workers):
        super().__init__(name, workers)
        self._slots = threading.BoundedSemaphore(workers)

    def _run(self, fn, args):
        try:
            return super()._run(fn, args)
        finally:
            self._slots.release()  # the slot frees when the WORKER finishes, not when the caller gives up

    def call(self, fn, *args, timeout):
        if not self._slots.acquire(blocking=False):  # bulkhead: fail fast instead of queueing behind stuck calls
            raise BulkheadFull(f"{self.name}: {self.workers} calls already in flight")
        return super().call(fn, *args, timeout=timeout)


class CircuitBreaker:
    """closed -> open when >= failure_rate of the last `window` calls failed; open -> half_open after open_s;
    one trial call in half_open: success -> closed, failure -> open again."""

    def __init__(self, name, window=10, min_calls=5, failure_rate=0.5, open_s=1.0, clock=time.monotonic, log=json_log):
        self.name, self.min_calls, self.failure_rate, self.open_s = name, min_calls, failure_rate, open_s
        self.clock, self.log, self.state, self.opened_at, self.trial = clock, log, "closed", 0.0, False
        self.results, self._lock = deque(maxlen=window), threading.Lock()  # count-based sliding window

    def _move(self, to, **why):
        self.log({"evt": "breaker", "name": self.name, "from": self.state, "to": to, **why})
        self.state = to
        if to == "open":
            self.opened_at = self.clock()

    def call(self, fn, *args, **kwargs):
        with self._lock:
            if self.state == "open":
                if self.clock() - self.opened_at < self.open_s:
                    raise CircuitOpen(f"{self.name}: circuit open, failing fast")  # no call, no waiting
                self._move("half_open")
            if self.state == "half_open":
                if self.trial:
                    raise CircuitOpen(f"{self.name}: half-open, trial call in progress")
                self.trial = True
        try:
            result = fn(*args, **kwargs)
        except Exception:
            self._record(False)
            raise
        self._record(True)
        return result

    def _record(self, ok):
        with self._lock:
            if self.state == "half_open":
                self.trial = False
                self.results.clear()
                self._move("closed" if ok else "open", trial="ok" if ok else "failed")
                return
            self.results.append(ok)
            rate = self.results.count(False) / len(self.results)
            if self.state == "closed" and len(self.results) >= self.min_calls and rate >= self.failure_rate:
                self._move("open", failure_rate=round(rate, 2), calls=len(self.results))


def with_fallback(call, fallback):
    """Fallback: a degraded answer for the errors we expect from a sick dependency. Returns (value, degraded)."""
    try:
        return call(), False
    except (TimeoutError, CircuitOpen, BulkheadFull, ConnectionError) as exc:
        return fallback(exc), True

"""Consumer-driven contracts, stdlib only (lesson 14 lab code). Same flow as Pact, NOT Pact's file format.

Consumer side: declare interactions -> run the real client against a mock provider -> write contracts/*.json.
Provider side: replay every interaction against the real provider and compare. Weakness (failureLab):
verify_provider() only compares status codes.
"""
import json
import pathlib
import threading
import urllib.error
import urllib.request
from contextlib import contextmanager
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


def like(example):
    """Matcher: any value of the same type as `example` (the consumer cares about the field, not the value)."""
    return {"$like": example}


def _example(body, rules, path="$"):  # strip matchers -> (example body, {json path: "type"})
    if isinstance(body, dict) and "$like" in body:
        rules[path] = "type"
        return body["$like"]
    if isinstance(body, dict):
        return {key: _example(value, rules, f"{path}.{key}") for key, value in body.items()}
    return body


class ContractBuilder:
    def __init__(self, consumer, provider, consumer_version):
        self.contract = {"consumer": consumer, "provider": provider, "interactions": [],
                         "metadata": {"format": "lesson-14 contract v1", "consumerVersion": consumer_version}}

    def interaction(self, description, state, method, path, status, body):
        rules = {}
        response = {"status": status, "body": _example(body, rules), "matchingRules": rules}
        self.contract["interactions"].append({"description": description, "providerState": state,
                                              "request": {"method": method, "path": path}, "response": response})
        return self

    @contextmanager
    def mock_provider(self):
        """Serve the declared responses; fail if the consumer skipped an interaction or sent an unexpected one."""
        routes = {(i["request"]["method"], i["request"]["path"]): i for i in self.contract["interactions"]}
        used, unexpected = set(), []

        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                found = routes.get(("GET", self.path))
                (used.add(("GET", self.path)) if found else unexpected.append(f"GET {self.path}"))
                status, body = (found["response"]["status"], found["response"]["body"]) if found else (500, {})
                data = json.dumps(body).encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def log_message(self, *args):
                pass

        server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        threading.Thread(target=server.serve_forever, daemon=True).start()
        try:
            yield f"http://127.0.0.1:{server.server_port}"
        finally:
            server.shutdown()
            server.server_close()
        missing = sorted(set(routes) - used)
        if unexpected or missing:
            raise AssertionError(f"mock provider: unexpected {unexpected}, never called {missing}")

    def write(self, folder):
        path = pathlib.Path(folder) / f"{self.contract['consumer']}--{self.contract['provider']}.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(self.contract, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        return path


def _request(base_url, method, path, body=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(base_url + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            return resp.status, json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        return exc.code, json.loads(exc.read().decode("utf-8") or "{}")


def verify_provider(contract_path, provider_url):
    """Replay each interaction against the REAL provider (after setting its state). Returns a list of problems."""
    contract = json.loads(pathlib.Path(contract_path).read_text(encoding="utf-8"))
    problems = []
    for item in contract["interactions"]:
        _request(provider_url, "POST", "/_contract/state", {"state": item["providerState"]})
        status, body = _request(provider_url, item["request"]["method"], item["request"]["path"])
        expected = item["response"]
        if status != expected["status"]:  # weakness: the body is never compared
            problems.append(f"{item['description']}: status {status}, contract says {expected['status']}")
    return problems

"""SLIs, SLOs and multiwindow burn-rate alerts from structured request logs (lesson 15 lab code).

Works for availability. Weakness (the failureLab): latency is only checked as an AVERAGE (mean <= 200 ms).
Run the demo: python app.py
"""
import bisect
import json
from datetime import datetime, timezone

PERIOD_DAYS = 30  # SLO period: error budget = (1 - SLO) x the requests in 30 days
# SLI = good events / valid events. name: (is the request valid for this SLI?, was it good?)
SLIS = {"availability": (lambda r: True, lambda r: r["status"] < 500)}
SLOS = {"availability": 0.999}
MEAN_LATENCY_LIMIT_MS = 200
# multiwindow, multi-burn-rate alerts (Google SRE Workbook, "Alerting on SLOs", table 5-8):
# (severity, long window s, short window s, burn-rate threshold); short window = 1/12 of the long one
ALERTS = [("page", 3600, 300, 14.4), ("page", 21600, 1800, 6.0), ("ticket", 259200, 21600, 1.0)]


def parse(lines):
    records = [json.loads(line) for line in lines if line.strip()]
    for r in records:
        r["t"] = datetime.strptime(r["ts"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc).timestamp()
    return sorted(records, key=lambda r: r["t"])


def window(records, now, seconds):  # records are sorted by time: binary search for [now - seconds, now)
    def at(t):
        return bisect.bisect_left(records, t, key=lambda r: r["t"])
    return records[at(now - seconds):at(now)]


def bad_ratio(records, sli):
    is_valid, is_good = SLIS[sli]
    valid = [r for r in records if is_valid(r)]
    return sum(not is_good(r) for r in valid) / len(valid) if valid else 0.0


def burn_rate(records, sli, now, seconds):
    # burn rate 1 = spending the budget exactly over the SLO period; 14.4 = 2% of a 30-day budget in 1 hour
    return bad_ratio(window(records, now, seconds), sli) / (1 - SLOS[sli])


def budget_consumed(records, sli, now, days=3):
    """Share of the 30-day error budget spent in the last `days` (= burn rate x window / period)."""
    return burn_rate(records, sli, now, days * 86400) * days / PERIOD_DAYS


def label(seconds):
    return f"{seconds // 86400}d" if seconds >= 86400 else f"{seconds // 3600}h" if seconds >= 3600 else f"{seconds // 60}m"


def alerts(records, now):
    fired = []
    for sli in SLOS:
        for severity, long_s, short_s, threshold in ALERTS:
            burn_long, burn_short = burn_rate(records, sli, now, long_s), burn_rate(records, sli, now, short_s)
            if burn_long >= threshold and burn_short >= threshold:  # both: fires fast AND resets fast
                fired.append({"sli": sli, "severity": severity, "windows": f"{label(long_s)}/{label(short_s)}",
                              "burn_long": round(burn_long, 1), "burn_short": round(burn_short, 1),
                              "threshold": threshold})
    return fired


def percentile(values, p):  # nearest-rank: the value at or below which p% of the requests fall
    ordered = sorted(values)
    return ordered[max(0, -(-len(ordered) * p // 100) - 1)]


def latency_report(records, now, seconds=3600):
    ms = [r["ms"] for r in window(records, now, seconds)]
    return {"mean": round(sum(ms) / len(ms), 1), "p50": percentile(ms, 50), "p95": percentile(ms, 95),
            "p99": percentile(ms, 99), "requests": len(ms)}


def latency_problems(records, now):
    mean = latency_report(records, now)["mean"]  # weakness: a mean hides a slow tail
    return [] if mean <= MEAN_LATENCY_LIMIT_MS else [f"mean latency {mean} ms > {MEAN_LATENCY_LIMIT_MS} ms"]
